$st='E:\WebAIBridge\app\data\state.json'; $ms='E:\WebAIBridge\app\data\managed-chat-status.json';
if(Test-Path $st){$s=Get-Content $st -Raw|ConvertFrom-Json; foreach($a in @($s.agentAssignments)){ if($a.state -in @('queued','dispatching','running','awaiting_evidence','blocked')){Write-Output ('A|'+$a.id+'|state='+$a.state+'|target='+$a.targetChatId+'|repo='+$a.repository+'|branch='+$a.branch+'|dispatch='+$a.dispatchCount+'|diag='+$a.lastDiagnostic)}}}
if(Test-Path $ms){$m=Get-Content $ms -Raw|ConvertFrom-Json; foreach($p in $m.chats.PSObject.Properties){$x=$p.Value; Write-Output ('C|'+$p.Name+'|name='+$x.name+'|gen='+$x.generating+'|high='+$x.highMode+'|err='+$x.lastError)}}
